SELECT COUNT(*)
FROM TAB_B
WHERE COL2 NOT IN (SELECT COL1 FROM TAB_A);

SELECT *
FROM TAB
WHERE COL IN ('A', 'B', NULL);

SELECT AVG(나이) AS 평균_나이
FROM TAB
GROUP BY 나이_그룹;

CREATE TABLE T (
  COL1 NUMBER PRIMARY KEY,
  COL2 NUMBER CHECK (COL2 > 500)
);
-- 수행 전 T는 비어 있다.

INSERT INTO T VALUES (500, 600);
UPDATE T SET COL2 = 400 WHERE COL1 = 500;
INSERT INTO T VALUES (500, 700);
INSERT INTO T VALUES (270, 800);
SELECT SUM(COL1) FROM T;

SELECT *
FROM T
WHERE COL1 LIKE 'A%';
